// 使用隔离真实数据库验证旧草稿、目录迁移和日期回拨，不改用户数据。
#include "store.h"
#include "workspace.h"
#include "dates.h"
#include "instance.h"
#include <sqlite3.h>
#include <chrono>
#include <filesystem>
#include <functional>
#include <iostream>
#include <stdexcept>

static void require(bool ok,const char* text){if(!ok)throw std::runtime_error(text);}
int main(){
    auto root=std::filesystem::temp_directory_path()/("litetodo-reliability-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));
    std::filesystem::create_directories(root);int failures=0,checks=0;
    auto test=[&](const char* name,const std::function<void()>& body){try{body();++checks;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failures;std::cout<<"FAIL "<<name<<": "<<e.what()<<'\n';}};
    test("stale state save is rejected",[&]{Store a(root/"state.sqlite3"),b(root/"state.sqlite3");auto id=a.add("original","",0);auto draft=b.list()[0];a.set_done(id,true);bool blocked=false;try{draft.note="old edit";b.save_task(draft,{});}catch(...){blocked=true;}require(blocked&&a.list()[0].done,"Old draft silently revoked completion");});
    test("stale task identity cannot overwrite replacement",[&]{Store a(root/"identity.sqlite3"),b(root/"identity.sqlite3");auto id=a.add("old","",0);auto draft=b.list()[0];a.remove(id);Task replacement;replacement.title="new";std::vector<Attachment> files={{"file","C:/demo/file"}};auto next=a.save_task(replacement,{{0,"new child",false}},&files);bool blocked=false;try{b.save_task(draft,{});}catch(...){blocked=true;}require(blocked&&a.list()[0].title=="new"&&a.children(next).size()==1&&a.attachments(next).size()==1,"Old draft overwrote new task or its relations");});
    test("child change invalidates old parent draft",[&]{Store a(root/"child.sqlite3"),b(root/"child.sqlite3");Task t;t.title="parent";auto id=a.save_task(t,{{0,"child",false}});auto draft=b.list()[0];auto children=b.children(id);a.set_child_done(children[0].id,true);bool blocked=false;try{b.save_task(draft,children);}catch(...){blocked=true;}require(blocked&&a.children(id)[0].done,"Old parent draft reverted changed child");});
    test("import invalidates pre-import draft",[&]{Store a(root/"import.sqlite3");a.add("same task","",0);auto draft=a.list()[0];a.backup(root/"snapshot.sqlite3");a.restore_from(root/"snapshot.sqlite3");bool blocked=false;try{draft.note="stale";a.save_task(draft,{});}catch(...){blocked=true;}require(blocked&&a.list()[0].note.empty(),"Pre-import draft accepted after replacing database");});
    test("failed migration can retry same path",[&]{Store a(root/"move.sqlite3");a.add("kept","",0);auto target=root/"destination.sqlite3";bool failed=false;try{a.relocate(target,[]{throw std::runtime_error("publish failure");});}catch(...){failed=true;}require(failed&&!std::filesystem::exists(target)&&a.list().size()==1,"Failed publication left candidate file");a.relocate(target);require(a.list().size()==1,"Retry lost original task");});
    test("failed migration preserves pre-existing destination",[&]{auto target=root/"existing.sqlite3";{Store other(target);other.add("other","",0);}Store a(root/"move-existing.sqlite3");bool blocked=false;try{a.relocate(target);}catch(...){blocked=true;}Store other(target);require(blocked&&other.list()[0].title=="other","Failure cleanup touched pre-existing data");});
    test("clock rollback retains today's successful backup",[&]{Store a(root/"clock.sqlite3");a.add("new work","",0);auto folder=root/"backups";std::filesystem::create_directories(folder);for(int i=1;i<=7;++i)a.backup(folder/("auto-"+date_text(day_after(i))+".sqlite3"));auto current=daily_backup(a,folder);int count=0;for(const auto& f:std::filesystem::directory_iterator(folder))if(f.is_regular_file())++count;require(std::filesystem::exists(current)&&count==7,"Today's snapshot immediately pruned during clock rollback");});
    test("data-directory instance lock and activation",[&]{auto folder=root/"instance";InstanceLock first(folder),second(folder),independent(root/"independent");require(first.owns()&&!second.owns()&&independent.owns(),"Same data directory did not exclude second instance");second.request_activation();require(first.consume_activation()&&!first.consume_activation(),"Activation was not consumed exactly once");first.swap(independent);InstanceLock blocked(root/"independent");require(!blocked.owns(),"Migration did not retain destination lock");});
    test("normal notification receipt keeps active draft valid",[&]{Store a(root/"receipt.sqlite3");auto id=a.add("task","",now_seconds()+20);auto draft=a.get(id);a.confirm_notification(id,draft.remind_at);draft.note="edited";a.save_task(draft,{});require(a.get(id).note=="edited","Passive notification receipt falsely invalidated draft");});
    test("attachment change invalidates parent draft",[&]{Store a(root/"file-conflict.sqlite3"),b(root/"file-conflict.sqlite3");Task task;task.title="file parent";auto id=a.save_task(task,{});auto old=b.get(id);auto fresh=a.get(id);std::vector<Attachment> files={{"new","C:/demo/new"}};a.save_task(fresh,{},&files);bool blocked=false;try{b.save_task(old,{});}catch(...){blocked=true;}require(blocked&&a.attachments(id).size()==1,"Old draft accepted after attachment change");});
    test("stale confirmation cannot delete or reschedule",[&]{Store a(root/"confirmation.sqlite3");auto id=a.add("task","",50);auto old=a.get(id);a.update(id,"changed","",50);bool delete_blocked=false,remind_blocked=false;try{a.remove(id,old.edit_token);}catch(...){delete_blocked=true;}try{a.reschedule(id,100,old.edit_token);}catch(...){remind_blocked=true;}require(delete_blocked&&remind_blocked&&a.get(id).title=="changed"&&a.get(id).remind_at==50,"Stale confirmation bypassed conflict check");});
    test("directory alias and release use same system lock",[&]{auto folder=root/"alias";{InstanceLock first(folder),alias(folder/".");require(first.owns()&&!alias.owns(),"Directory alias bypassed lock");}InstanceLock restarted(folder);require(restarted.owns(),"Lock was not released on destruction");});
    test("v5 upgrade preserves data and pre-upgrade snapshot",[&]{
        auto file=root/"version5.sqlite3";
        {Store seed(file);Task task;task.title="v5 parent";task.shelved=true;std::vector<Attachment> files={{"attachment","C:/demo/file"}};seed.save_task(task,{{0,"child",true}},&files);seed.set_setting("theme","2");}
        sqlite3* db=nullptr;require(sqlite3_open(file.u8string().c_str(),&db)==SQLITE_OK,"Open v5 fixture");
        auto result=sqlite3_exec(db,"DROP TRIGGER tasks_edit_insert;DROP TRIGGER tasks_edit_update;DROP TRIGGER children_edit_insert;DROP TRIGGER children_edit_update;DROP TRIGGER children_edit_delete;DROP TRIGGER attachments_edit_insert;DROP TRIGGER attachments_edit_update;DROP TRIGGER attachments_edit_delete;DROP TRIGGER tasks_id_insert;DROP TABLE task_ids;ALTER TABLE tasks DROP COLUMN edit_token;PRAGMA user_version=5;",nullptr,nullptr,nullptr);sqlite3_close(db);require(result==SQLITE_OK,"Prepare authentic v5 schema");
        {Store upgraded(file);auto task=upgraded.list()[0];require(task.title=="v5 parent"&&task.shelved&&task.edit_token.size()==32&&upgraded.children(task.id)[0].done&&upgraded.attachments(task.id).size()==1&&upgraded.setting("theme")=="2","Upgrade changed original data");}
        bool preserved=false;for(const auto& entry:std::filesystem::directory_iterator(root))if(entry.path().filename().u8string().find("version5.sqlite3.pre-v6-")==0){require(sqlite3_open_v2(entry.path().u8string().c_str(),&db,SQLITE_OPEN_READONLY,nullptr)==SQLITE_OK,"Read upgrade snapshot");sqlite3_stmt* query=nullptr;sqlite3_prepare_v2(db,"PRAGMA user_version",-1,&query,nullptr);sqlite3_step(query);preserved=sqlite3_column_int(query,0)==5;sqlite3_finalize(query);sqlite3_close(db);}require(preserved,"Missing original v5 snapshot");
    });
    test("deleted task ID cannot be reused by late notification",[&]{Store a(root/"late-receipt.sqlite3");auto at=now_seconds()-1;auto old=a.add("old reminder","",at);a.remove(old);auto replacement=a.add("new reminder","",at);a.confirm_notification(old,at);require(replacement>old&&a.due(now_seconds()).size()==1,"Old notification receipt consumed replacement reminder");});
    test("task ID high-water mark survives restart",[&]{auto path=root/"restart-id.sqlite3";long long old=0;{Store a(path);old=a.add("deleted","",0);a.remove(old);}Store b(path);require(b.add("next","",0)>old,"Restart reused deleted maximum task ID");});
    test("older backup import retains task ID high-water mark",[&]{Store a(root/"import-ids.sqlite3");a.add("kept","",0);a.backup(root/"old-ids.sqlite3");auto old=a.add("later","",0);a.remove(old);a.restore_from(root/"old-ids.sqlite3");require(a.add("after import","",0)>old,"Import rolled task ID sequence backwards");});
    std::cout<<checks<<" reliability checks passed, "<<failures<<" failed\n";
    std::filesystem::remove_all(root);return failures?1:0;
}
